    @EventHandler( payloadType=UpdateSupplierEvent.class )
    public void handle( UpdateSupplierEvent event) {
    	LOGGER.info("handling UpdateSupplierEvent - " + event );
    	
	    Supplier entity = new Supplier();
            entity.setSupplierId( event.getSupplierId() );
            entity.setName( event.getName() );
            entity.setSupplierCode( event.getSupplierCode() );
            entity.setAddress( event.getAddress() );
            entity.setEnterprises( event.getEnterprises() );
            entity.setItems( event.getItems() );
            entity.setPurchaseOrders( event.getPurchaseOrders() );
            entity.setSupplierTier( event.getSupplierTier() );
            entity.setPaymentTerms( event.getPaymentTerms() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindSupplier( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllSupplier( entity );        
    }
    
