    /**
     * Method to retrieve the Supplier via an SupplierPrimaryKey.
     * @param 	id Long
     * @return 	Supplier
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Supplier handle( FindSupplierQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getSupplierId() );
    }
    
    /**
     * Method to retrieve a collection of all Suppliers
     *
     * @param	query	FindAllSupplierQuery 
     * @return 	List<Supplier> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Supplier> handle( FindAllSupplierQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindSupplier,
 * but only if the id matches
 *
 * @param		entity	Supplier
 */
	protected void emitFindSupplier( Supplier entity ) {
		LOGGER.info("handling emitFindSupplier" );
		
	    queryUpdateEmitter.emit(FindSupplierQuery.class,
	                            query -> query.getFilter().getSupplierId().equals(entity.getSupplierId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllSupplier
	 * 
	 * @param		entity	Supplier
	 */
	protected void emitFindAllSupplier( Supplier entity ) {
		LOGGER.info("handling emitFindAllSupplier" );
		
	    queryUpdateEmitter.emit(FindAllSupplierQuery.class,
	                            query -> true,
	                            entity);
	}

